// Minimal C impl (conceptual)
#include "header.h"
#include <stdlib.h>
#include <string.h>
MyItem* create_item(int seed, int* err) {
  if (seed <= 0) { *err = 1; return NULL; }
  MyItem* it = (MyItem*)malloc(sizeof(MyItem));
  if (!it) { *err = 2; return NULL; }
  it->id = seed;
  it->score = (double)seed;
  it->label = strdup("item");
  *err = 0;
  return it;
}
